class Solution {
    public int[] leftRightDifference(int[] nums) {
        int total = 0;
        for (int n : nums) total += n;
        int[] ans = new int[nums.length];
        int leftSum = 0;
        for (int i = 0; i < nums.length; i++) {
            int rightSum = total - leftSum - nums[i];
            ans[i] = Math.abs(leftSum - rightSum);
            leftSum += nums[i];
        }
        return ans;
    }
}
